"""Capacity ladder: linear booster and additive (depth-1) trees vs depth 2/3. Diagnostics only."""
import sys, warnings; warnings.filterwarnings('ignore'); sys.path.insert(0,'scratch')
from lab import *
import lab, types, e11
CATS=e11.CATS
def linear(alpha=0.0,lam=1.0,n=400):
    def prepare(st,X):
        out={}
        for c in st['num']:
            v=pd.to_numeric(X[c],errors='coerce').astype(float)
            if c in ('avg_daily_effluent_volume_m3','prior_year_worst_margin'): v=np.log1p(v)
            out[c]=((v-st['mu'][c])/st['sd'][c]).fillna(0.0).to_numpy(); out[c+'_na']=v.isna().astype(float).to_numpy()
        for c in st['cats']:
            for lv in st['levels'][c]: out[c+'='+''.join(ch if ch.isalnum() else '_' for ch in lv)]=(X[c]==lv).astype(float).to_numpy()
        return pd.DataFrame(out,index=X.index)
    def fit(X,y,*,seed,threads):
        X=X.reset_index(drop=True); cats=[c for c in CATS if c in X]; num=[c for c in X if c not in cats]
        st={'num':num,'cats':cats,'levels':{c:sorted(X[c].dropna().unique()) for c in cats},'mu':{},'sd':{}}
        for c in num:
            v=pd.to_numeric(X[c],errors='coerce').astype(float)
            if c in ('avg_daily_effluent_volume_m3','prior_year_worst_margin'): v=np.log1p(v)
            st['mu'][c]=float(v.mean()); st['sd'][c]=float(v.std() or 1.0)
        m=xgb.XGBClassifier(booster='gblinear',n_estimators=n,learning_rate=0.3,reg_alpha=alpha,reg_lambda=lam,random_state=seed,n_jobs=threads)
        m.fit(prepare(st,X),y); st['model']=m; return st
    return types.SimpleNamespace(fit=fit,prepare=prepare)
def show(name,m,seeds=(42,1,2)):
    v=[];b=[];br=[]
    for s in seeds:
        r=lab.run(m,seed=s); v.append(r['val_auc']); b.append(r['bt_auc']); br.append(r['val_brier'])
    print(f"{name:40s} val42 {v[0]:.5f} mean {np.mean(v):.5f} | bt {np.mean(b):.5f} | brier {np.mean(br):.5f}",flush=True)
show('gblinear lam1',linear(),seeds=(42,))
show('gblinear lam0.01',linear(lam=0.01),seeds=(42,))
show('depth1 x1600 mono',e11.make(params={**e11.PARAMS,'max_depth':1,'n_estimators':1600}))
show('depth2 x800 mono',e11.make())
show('depth3 x600 mono',e11.make(params={**e11.PARAMS,'max_depth':3,'n_estimators':600}))
show('depth6 x300 mono regularized',e11.make(params={**e11.PARAMS,'max_depth':6,'n_estimators':300}))
EOF
