"""Dropping 2015 rows (no limit history) costs 0.0026. H: static effects are data-limited, so
(a) up-weighting no-history rows or (b) adding history-masked copies of later rows may help. Diagnostic."""
import sys, warnings; warnings.filterwarnings('ignore'); sys.path.insert(0,'scratch')
from lab import *
import lab, types, e11
HIST=['prior_year_exceedance','prior_year_worst_margin','ever_exceeded_before']
def make(w_nohist=1.0, aug_w=0.0, params=e11.PARAMS):
    base=e11.make(params=params)
    def fit(X,y,*,seed,threads):
        X=X.reset_index(drop=True); y=np.asarray(y)
        cats=[c for c in e11.CATS if c in X]; num=[c for c in X if c not in cats]
        st={'num':num,'cats':cats,'levels':{c:pd.Index(sorted(X[c].dropna().unique())) for c in cats}}
        noh=(X['prior_year_exceedance'].isna()&X['ever_exceeded_before'].isna()).to_numpy()
        w=np.where(noh,w_nohist,1.0); Xf=X; yf=y
        if aug_w>0:
            A=X[~noh].copy()
            for c in HIST: A[c]=np.nan
            Xf=pd.concat([X,A],ignore_index=True); yf=np.concatenate([y,y[~noh]]); w=np.concatenate([w,np.full((~noh).sum(),aug_w)])
        Z=base.prepare(st,Xf)
        mono={c:(1 if c in e11.MONO_UP else 0) for c in Z.columns}
        m=xgb.XGBClassifier(tree_method='hist',enable_categorical=True,random_state=seed,n_jobs=threads,monotone_constraints=mono,**params)
        m.fit(Z,yf,sample_weight=w); st['model']=m; return st
    return types.SimpleNamespace(fit=fit,prepare=base.prepare)
def show(name,m,seeds=(42,1,2,3,4)):
    v=[];b=[];br=[]
    for s in seeds:
        r=lab.run(m,seed=s); v.append(r['val_auc']); b.append(r['bt_auc']); br.append(r['val_brier'])
    print(f"{name:30s} val42 {v[0]:.5f} mean {np.mean(v):.5f} sd {np.std(v):.5f} | bt {np.mean(b):.5f} | brier {np.mean(br):.5f}",flush=True)
if __name__=='__main__':
    show('ref',make())
    for w in (0.5,1.5,2,3,5): show(f'w_nohist {w}',make(w_nohist=w))
    for a in (0.1,0.25,0.5,1.0): show(f'hist-masked aug w={a}',make(aug_w=a))
    show('w_nohist 2 + aug .25',make(w_nohist=2,aug_w=0.25))
