"""H: log-loss optimizes calibration; a pairwise (AUC-surrogate) objective in the same single XGBClassifier may rank
better. Custom objective keeps the booster's logistic output transform, so predict_proba stays in (0,1). Diagnostic."""
import sys, warnings, time; warnings.filterwarnings('ignore'); sys.path.insert(0,'scratch')
from lab import *
import lab, types, e11
def pairwise_obj(mix, M, seed):
    rng=np.random.RandomState(seed)
    def obj(y, s):
        y=np.asarray(y); s=np.asarray(s,dtype=float); pos=np.flatnonzero(y==1); neg=np.flatnonzero(y==0); n=len(y)
        g=np.zeros(n); h=np.zeros(n)
        sp=s[rng.choice(pos,M)]; sn=s[rng.choice(neg,M)]
        # positives vs sampled negatives: loss log(1+exp(-(s_i - s_j)))
        d=1/(1+np.exp(s[pos][:,None]-sn[None,:]))          # sigma(s_j - s_i)
        g[pos]=-d.mean(1); h[pos]=(d*(1-d)).mean(1)
        d=1/(1+np.exp(sp[None,:]-s[neg][:,None]))          # sigma(s_j - s_i) for negative j
        g[neg]=d.mean(1); h[neg]=(d*(1-d)).mean(1)
        wp=0.5*n/len(pos); wn=0.5*n/len(neg)
        g[pos]*=wp; h[pos]*=wp; g[neg]*=wn; h[neg]*=wn
        if mix<1:
            p=1/(1+np.exp(-s)); g=mix*g+(1-mix)*(p-y); h=mix*h+(1-mix)*p*(1-p)
        return g, np.maximum(h,1e-6)
    return obj
def make(mix=1.0, M=256, params=e11.PARAMS):
    def prepare(st,X):
        out={}
        for c in st['num']: out[c]=pd.to_numeric(X[c],errors='coerce').astype(float).to_numpy()
        out=pd.DataFrame(out,index=X.index)
        v=out['avg_daily_effluent_volume_m3'].to_numpy().copy(); v[np.isnan(v)&(out['periods_reported_prior_year'].to_numpy()>0)]=-1.0; out['avg_daily_effluent_volume_m3']=v
        for c in st['cats']: out[c]=pd.Categorical(X[c],categories=st['levels'][c])
        return out
    def fit(X,y,*,seed,threads):
        X=X.reset_index(drop=True); y=np.asarray(y)
        cats=[c for c in e11.CATS if c in X]; num=[c for c in X if c not in cats]
        st={'num':num,'cats':cats,'levels':{c:pd.Index(sorted(X[c].dropna().unique())) for c in cats}}
        Z=prepare(st,X); mono={c:(1 if c in e11.MONO_UP else 0) for c in Z.columns}
        kw={} if mix==0 else {'objective':pairwise_obj(mix,M,seed)}
        m=xgb.XGBClassifier(tree_method='hist',enable_categorical=True,random_state=seed,n_jobs=threads,monotone_constraints=mono,**params,**kw)
        m.fit(Z,y); st['model']=m; return st
    return types.SimpleNamespace(fit=fit,prepare=prepare)
def show(name,m,seeds=(42,1,2)):
    v=[];b=[];br=[]; t=time.time()
    for s in seeds:
        r=lab.run(m,seed=s); v.append(r['val_auc']); b.append(r['bt_auc']); br.append(r['val_brier'])
    print(f"{name:40s} val42 {v[0]:.5f} mean {np.mean(v):.5f} sd {np.std(v):.5f} | bt {np.mean(b):.5f} | brier {np.mean(br):.5f} | {time.time()-t:.0f}s",flush=True)
if __name__=='__main__':
    P=e11.PARAMS
    show('logloss (trial 6)',make(mix=0))
    show('pairwise',make(mix=1.0))
    show('pairwise, lr .04',make(mix=1.0,params={**P,'learning_rate':0.04}))
    show('pairwise, 1600 trees',make(mix=1.0,params={**P,'n_estimators':1600}))
    show('mix 0.5',make(mix=0.5))
    show('mix 0.25',make(mix=0.25))
    show('pairwise depth 3 x600',make(mix=1.0,params={**P,'max_depth':3,'n_estimators':600}))
